export type ColorSpace = 'hex' | 'rgb' | 'hsl' | 'lab' | 'lch' | 'oklab' | 'oklch';

export interface RgbValue {
  r: number; // 0-255
  g: number; // 0-255
  b: number; // 0-255
}

export interface HslValue {
  h: number; // 0-360
  s: number; // 0-100
  l: number; // 0-100
}

export interface LabValue {
  l: number; // 0-100
  a: number; // roughly -125..125
  b: number; // roughly -125..125
}

export interface LchValue {
  l: number; // 0-100
  c: number; // roughly 0-150
  h: number; // 0-360
}

export interface OklabValue {
  l: number; // 0-1
  a: number; // roughly -0.4..0.4
  b: number; // roughly -0.4..0.4
}

export interface OklchValue {
  l: number; // 0-1
  c: number; // roughly 0-0.4
  h: number; // 0-360
}

export interface ColorValueMap {
  hex: string;
  rgb: RgbValue;
  hsl: HslValue;
  lab: LabValue;
  lch: LchValue;
  oklab: OklabValue;
  oklch: OklchValue;
}

export const COLOR_SPACES: ColorSpace[] = ['hex', 'rgb', 'hsl', 'lab', 'lch', 'oklab', 'oklch'];

export const COLOR_SPACE_LABELS: Record<ColorSpace, string> = {
  hex: 'HEX',
  rgb: 'RGB',
  hsl: 'HSL',
  lab: 'LAB',
  lch: 'LCH',
  oklab: 'OKLab',
  oklch: 'OKLCH',
};
