import type { FC } from 'react';
import { useState } from 'react';
import { Copy, Check } from 'lucide-react';
import { toast } from 'sonner';
import { COLOR_SPACES, COLOR_SPACE_LABELS, type ColorSpace, type ColorValueMap } from '@/lib/color/types';
import { formatColorValue } from '@/lib/color/convert';

interface ResultGridProps {
  results: ColorValueMap;
}

const ResultGrid: FC<ResultGridProps> = ({ results }) => {
  const [copiedSpace, setCopiedSpace] = useState<ColorSpace | null>(null);

  const handleCopy = async (space: ColorSpace, text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedSpace(space);
      toast.success(`Copied ${COLOR_SPACE_LABELS[space]}`);
      window.setTimeout(() => setCopiedSpace((current) => (current === space ? null : current)), 1500);
    } catch {
      toast.error('Copy failed');
    }
  };

  return (
    <div className="grid grid-cols-1 gap-2">
      {COLOR_SPACES.map((space) => {
        const text = formatColorValue(space, results[space]);
        const isCopied = copiedSpace === space;

        return (
          <div
            key={space}
            className="glass-panel hover:border-border flex items-center gap-3 px-4 py-2.5"
          >
            <span className="text-xs font-medium text-muted-foreground w-14 shrink-0">
              {COLOR_SPACE_LABELS[space]}
            </span>
            <span className="font-mono text-sm text-foreground truncate flex-1 min-w-0">{text}</span>
            <button
              type="button"
              onClick={() => handleCopy(space, text)}
              aria-label={`Copy ${COLOR_SPACE_LABELS[space]} value`}
              className="shrink-0 p-2 rounded-full text-muted-foreground hover:text-accent hover:bg-accent/10 transition-colors"
            >
              {isCopied ? <Check className="w-4 h-4 text-accent" /> : <Copy className="w-4 h-4" />}
            </button>
          </div>
        );
      })}
    </div>
  );
};

export default ResultGrid;
