import type { FC } from 'react';
import type {
  ColorSpace,
  ColorValueMap,
  HslValue,
  LabValue,
  LchValue,
  OklabValue,
  OklchValue,
  RgbValue,
} from '@/lib/color/types';
import { Input } from '@/components/ui/input';
import NumberField from './NumberField';

interface ColorInputProps {
  space: ColorSpace;
  value: ColorValueMap[ColorSpace];
  onChange: (value: ColorValueMap[ColorSpace]) => void;
  error: string | null;
}

const ColorInput: FC<ColorInputProps> = ({ space, value, onChange, error }) => {
  const fields = (() => {
    switch (space) {
      case 'hex':
        return (
          <div>
            <label className="block text-xs font-medium text-muted-foreground mb-1.5">Hex</label>
            <Input
              type="text"
              value={value as string}
              onChange={(e) => onChange(e.target.value)}
              placeholder="#3b82f6"
              className="font-mono uppercase"
              maxLength={7}
              spellCheck={false}
            />
          </div>
        );

      case 'rgb': {
        const v = value as RgbValue;
        return (
          <div className="grid grid-cols-3 gap-3">
            <NumberField label="R" value={v.r} min={0} max={255} onChange={(n) => onChange({ ...v, r: n })} />
            <NumberField label="G" value={v.g} min={0} max={255} onChange={(n) => onChange({ ...v, g: n })} />
            <NumberField label="B" value={v.b} min={0} max={255} onChange={(n) => onChange({ ...v, b: n })} />
          </div>
        );
      }

      case 'hsl': {
        const v = value as HslValue;
        return (
          <div className="grid grid-cols-3 gap-3">
            <NumberField label="H" value={v.h} min={0} max={360} onChange={(n) => onChange({ ...v, h: n })} />
            <NumberField label="S %" value={v.s} min={0} max={100} onChange={(n) => onChange({ ...v, s: n })} />
            <NumberField label="L %" value={v.l} min={0} max={100} onChange={(n) => onChange({ ...v, l: n })} />
          </div>
        );
      }

      case 'lab': {
        const v = value as LabValue;
        return (
          <div className="grid grid-cols-3 gap-3">
            <NumberField label="L" value={v.l} min={0} max={100} onChange={(n) => onChange({ ...v, l: n })} />
            <NumberField label="a" value={v.a} min={-125} max={125} onChange={(n) => onChange({ ...v, a: n })} />
            <NumberField label="b" value={v.b} min={-125} max={125} onChange={(n) => onChange({ ...v, b: n })} />
          </div>
        );
      }

      case 'lch': {
        const v = value as LchValue;
        return (
          <div className="grid grid-cols-3 gap-3">
            <NumberField label="L" value={v.l} min={0} max={100} onChange={(n) => onChange({ ...v, l: n })} />
            <NumberField label="C" value={v.c} min={0} max={150} onChange={(n) => onChange({ ...v, c: n })} />
            <NumberField label="H" value={v.h} min={0} max={360} onChange={(n) => onChange({ ...v, h: n })} />
          </div>
        );
      }

      case 'oklab': {
        const v = value as OklabValue;
        return (
          <div className="grid grid-cols-3 gap-3">
            <NumberField label="L" value={v.l} min={0} max={1} step={0.01} onChange={(n) => onChange({ ...v, l: n })} />
            <NumberField label="a" value={v.a} min={-0.4} max={0.4} step={0.001} onChange={(n) => onChange({ ...v, a: n })} />
            <NumberField label="b" value={v.b} min={-0.4} max={0.4} step={0.001} onChange={(n) => onChange({ ...v, b: n })} />
          </div>
        );
      }

      case 'oklch': {
        const v = value as OklchValue;
        return (
          <div className="grid grid-cols-3 gap-3">
            <NumberField label="L" value={v.l} min={0} max={1} step={0.01} onChange={(n) => onChange({ ...v, l: n })} />
            <NumberField label="C" value={v.c} min={0} max={0.4} step={0.001} onChange={(n) => onChange({ ...v, c: n })} />
            <NumberField label="H" value={v.h} min={0} max={360} onChange={(n) => onChange({ ...v, h: n })} />
          </div>
        );
      }

      default:
        return null;
    }
  })();

  return (
    <div>
      {fields}
      {error && <p className="text-xs text-destructive mt-2">{error}</p>}
    </div>
  );
};

export default ColorInput;
